import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

class Solution {
    public List<List<Integer>> threeSum(int[] nums) {
        Arrays.sort(nums);
        List<List<Integer>> result = new ArrayList<>();
        for (int anchor = 0; anchor < nums.length - 2; anchor++) {
            if (anchor > 0 && nums[anchor] == nums[anchor - 1]) continue;
            if (nums[anchor] > 0) break;
            int left = anchor + 1;
            int right = nums.length - 1;
            while (left < right) {
                long sum = (long) nums[anchor] + nums[left] + nums[right];
                if (sum == 0) {
                    result.add(Arrays.asList(nums[anchor], nums[left], nums[right]));
                    int leftValue = nums[left];
                    int rightValue = nums[right];
                    while (left < right && nums[left] == leftValue) left++;
                    while (left < right && nums[right] == rightValue) right--;
                } else if (sum < 0) {
                    left++;
                } else {
                    right--;
                }
            }
        }
        return result;
    }
}
